(* [comment removed for export] *)
(* [comment removed for export] *)
Definition P_UB_VEC_STATEP_EMPLACE_BACK : Z := 0x3a254.
Definition P_EB_RET1 : Z := 0x3a588.   (* [comment removed for export] *)
Definition P_EB_RET2 : Z := 0x3a2ec.   (* [comment removed for export] *)
Definition EMPLACE_BACK_STACK : Z := 128 + ROPNEW_STACK.   (* [comment removed for export] *)

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Definition eb_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (V X lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk junk0,
      ms' = MS (mkR (Z_to_bv 64 P_EB_RET1) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2
                    (Z_to_bv 64 1) (Z_to_bv 64 0) (Z_to_bv 64 8) (Z_to_bv 64 1) a2 a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -128)
      /\ rw_cells usegs m' (bv_unsigned sp + -80) [CB 32 junk; C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 V); C8 s2; C8 s1; C8 s0; C8 ra]
      /\ rw_cells usegs m' (bv_unsigned sp + -112) [CB 8 junk0; C8 (Z_to_bv 64 X); C8 (Z_to_bv 64 V); C8 (Z_to_bv 64 P_EB_RET2)]
      /\ rw_cells usegs m' (bv_unsigned sp + -128) [C8 (Z_to_bv 64 (bv_unsigned sp + -72)); C8 (Z_to_bv 64 0x3a3a8)].
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.

  Lemma eb_seg1 : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (V X lo : Z),
    rw_cells usegs m V [C8 (wz 0); C8 (wz 0); C8 (wz 0)] ->
    stk usegs m lo (bv_unsigned sp) -> lo + 128 <= bv_unsigned sp ->
    (V + 24 <= lo \/ bv_unsigned sp <= V) ->
    mem_inv usegs m ->
    evt usegs (eb_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc V X lo m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 V) (Z_to_bv 64 X) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
