  (* [comment removed for export] *)
  Definition eb_seg2a_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (V X A lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j8,
      ms' = MS (mkR (Z_to_bv 64 P_EB_RET2) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                    (Z_to_bv 64 V) (Z_to_bv 64 X) (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_EB_RET2) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
