  (* [comment removed for export] *)
  Definition eb_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (V A x lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp); (V, V + 24); (A, A + 8)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' V [C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 (A + 8)); C8 (Z_to_bv 64 (A + 8))]
      /\ rw_cells usegs m' A [C8 (Z_to_bv 64 x)].

  Lemma eb_seg2b : forall (ra sp : word) gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (V X A x lo : Z) (j8 junkA : list byte),
    rw_cells usegs m (bv_unsigned sp + -80)
       [CB 8 j8; C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 (8 + A)); C8 (Z_to_bv 64 V); C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells usegs m V [C8 (wz 0); C8 (wz 0); C8 (wz 0)] ->
    ro_cells usegs m X [C8 (wz x)] ->
    rw_cells usegs m A [CB 8 junkA] ->
    stk usegs m lo (bv_unsigned sp + -80) -> lo + 128 <= bv_unsigned sp ->
    (V + 24 <= lo \/ bv_unsigned sp <= V) -> (X + 8 <= lo \/ bv_unsigned sp <= X) ->
    (X + 8 <= A \/ A + 8 <= X) -> (V + 24 <= A \/ A + 8 <= V) -> (X + 8 <= V \/ V + 24 <= X) ->
    rblock_range A 8 -> hceil <= lo -> 0 <= x < 2^64 ->
    mem_inv usegs m ->
    evt usegs (eb_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc V A x lo m)
      (MS (mkR (Z_to_bv 64 P_EB_RET2) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
               (Z_to_bv 64 V) (Z_to_bv 64 X) (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
