(* [comment removed for export] *)
Definition VEC_READOP_RESERVE_STACK : Z := 64.

Definition vec_readop_reserve0_post (ra sp gp tp s0 s1 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp).

Definition vec_readop_reserve0_stmt : Prop :=
  forall (V vb ve vc lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_cells usegs m V [C8 (wz vb); C8 (wz ve); C8 (wz vc)] -> 0 <= vb < 2^64 -> 0 <= vc < 2^64 ->
  stk usegs m lo (bv_unsigned sp) -> lo + VEC_READOP_RESERVE_STACK <= bv_unsigned sp -> hceil <= lo ->
  (V + 24 <= lo \/ bv_unsigned sp <= V) ->
  mem_inv usegs m ->
  evt usegs (vec_readop_reserve0_post ra sp gp tp s0 s1 (wz 0) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz V) (wz 0) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_VEC_READOP_RESERVE) fc None m (seg_rom usegs)).

